/// <reference lib="WebWorker" />
/**
 * Diff worker entry. Built as a separate rollup output (`dist/worker.js`).
 *
 * The worker is intentionally narrow: it consumes a `ComputeRequest` and posts back
 * the flat encoding of the `DiffResult`, which the main thread decodes with the
 * modified text it already has.
 */

import { _TsDiffComputer } from '../api/tsDiffComputer.js';
import { _encodeFlatDiff } from '../api/flatDiffResult.js';
import { initWasm, getWasm } from '../wasm/loader.js';
import { computeWasmDiff } from '../wasm/wasmDiff.js';
import type {
    ComputeRequest,
    ComputeResponse,
    InitRequest,
    InitResponse,
    WorkerRequest,
} from './protocol.js';

const tsImpl = new _TsDiffComputer(undefined);

self.addEventListener('message', (ev: MessageEvent<WorkerRequest>) => {
    const msg = ev.data;
    if (msg.kind === 'init') {
        void handleInit(msg);
    } else if (msg.kind === 'computeDiff') {
        void handleCompute(msg);
    }
});
async function handleInit(req: InitRequest): Promise<void> {
    try {
        if (req.backend === 'wasm') {
            await initWasm();
        }
        const resp: InitResponse = { kind: 'init', id: req.id, ok: true };
        self.postMessage(resp);
    } catch (err) {
        const resp: ComputeResponse = {
            kind: 'computeDiff',
            id: req.id,
            ok: false,
            error: String(err instanceof Error ? err.message : err),
        };
        self.postMessage(resp);
    }
}

async function handleCompute(req: ComputeRequest): Promise<void> {
    try {
        let result: Uint32Array;
        if (req.backend === 'ts') {
            result = _encodeFlatDiff(tsImpl.computeDiff(req.original, req.modified, req.options));
        } else {
            await initWasm();
            result = computeWasmDiff(getWasm(), req.original, req.modified, req.options);
        }
        const resp: ComputeResponse = { kind: 'computeDiff', id: req.id, ok: true, result };
        self.postMessage(resp, [result.buffer]);
    } catch (err) {
        const resp: ComputeResponse = {
            kind: 'computeDiff',
            id: req.id,
            ok: false,
            error: String(err instanceof Error ? err.message : err),
        };
        self.postMessage(resp);
    }
}